using Backend.Persistence.Data; using Backend.Persistence.Domain; using Microsoft.EntityFrameworkCore;
namespace Backend.Api.Apis; public static class WorkspaceEndpoints { public static IEndpointRouteBuilder MapWorkspaceEndpoints(this IEndpointRouteBuilder app) { var group=app.MapGroup("/workspaces").WithTags("Workspaces"); group.MapPost("", async (CreateWorkspace request, AppDbContext db, ILoggerFactory lf) => { if(string.IsNullOrWhiteSpace(request.Name)||string.IsNullOrWhiteSpace(request.Slug)||string.IsNullOrWhiteSpace(request.PlatformRef)) return Results.UnprocessableEntity(); var w=new Workspace{Name=request.Name,Slug=request.Slug,PlatformRef=request.PlatformRef,Platform=request.Platform}; db.Workspaces.Add(w); await db.SaveChangesAsync(); lf.CreateLogger("Workspace").LogInformation("Workspace created {WorkspaceId}",w.Id); return Results.Created($"/workspaces/{w.Id}",w); }); group.MapGet("/{id:long}", async (long id, AppDbContext db)=>await db.Workspaces.FindAsync(id) is { } w ? Results.Ok(w) : Results.NotFound()); return app; } public sealed record CreateWorkspace(string Name,string Slug,string PlatformRef,WorkspacePlatform Platform=WorkspacePlatform.Github); }